4|import { expect, test } from '@playwright/test';
5|
6|const PROTECTED_ADMIN_ENDPOINTS = [
7|  { method: 'GET', path: '/api/admin/sources' },
8|  { method: 'GET', path: '/api/admin/reviews' },
9|  { method: 'GET', path: '/api/admin/inbox/runs' },
10|  { method: 'POST', path: '/api/admin/radar/refresh' },
11|];
