13|test.describe('Admin boundary', () => {
14|  test('unauthenticated admin requests are rejected with 401', async ({ page }) => {
15|    await page.goto('/');
16|
17|    for (const { method, path } of PROTECTED_ADMIN_ENDPOINTS) {
18|      // page.request dùng network stack của chính context (cùng origin,
19|      // không có cookie/header credential nào).
20|      const response = await page.request.fetch(path, { method });
