24|      const body = await response.text();
25|      expect(body.length).toBeGreaterThan(0);
26|      const detail = JSON.parse(body)?.detail ?? '';
27|      expect(detail).not.toMatch(/ADMIN_TOKEN=|token is:|expected token/i);
28|    }
29|  });
