{"content": "1|// Shared assertions cho journey "public" (desktop + mobile) — task q2-browser-e2e.
2|// Không có secret nào ở đây; chỉ kiểm tra dữ liệu public.
3|import { expect } from '@playwright/test';
4|
5|import { CONTENT_GROUPS, DEFAULT_GROUP_ID } from '../src/data/groups.js';
6|
7|// Marker của source registry / provenance nội bộ — không bao giờ được lộ ra
8|// UI public hay response /api/*. Nếu backend thêm field nội bộ mới, test phải
9|// cập nhật danh sách này.
10|export const PROVENANCE_MARKERS = [
11|  'source_id',
12|  'data_origin',
13|  'provenance',
14|  'registry',
15|  'quarantine',
16|  'sample_rss_demo',
17|  'sample_manual_demo',
18|];
19|
20|export const ARTICLES_PUBLIC_FIELDS = new Set([
21|  'id', 'title', 'url', 'source', 'category', 'summary', 'published_at', 'created_at',
22|]);
23|
24|export async function expectBrandedShell(page) {
25|  await expect(page).toHaveTitle('Vũ Học AI Radar v1.0');
26|  await expect(page.locator('.brand-badge')).toHaveText('VŨ HỌC');
27|  await expect(page.locator('h1.brand-title')).toHaveText('AI Radar');
28|}
29|
30|export async function expectAllNavigationGroups(items) {
31|  expect(items).toHaveCount(CONTENT_GROUPS.length); // 7 nhóm
32|  const names = await items.allTextContents();
33|  expect(names.map((n) => n.trim())).toEqual(CONTENT_GROUPS.map((g) => g.name));
34|}
35|
36|// Gọi public feed qua đúng origin của browser context (đi qua proxy Vite
37|// như người dùng thực), rồi kiểm tra: 200, array, chỉ có field public,
38|// không marker registry/provenance trong cả raw response.
39|export async function expectPublicFeedClean(page) {
40|  const response = await page.request.get('/api/articles');
41|  expect(response.status()).toBe(200);
42|
43|  const raw = await response.text();
44|  const lowered = raw.toLowerCase();
45|  for (const marker of PROVENANCE_MARKERS) {
46|    expect(lowered, `marker nội bộ "${marker}" lộ trong /api/articles`).not.toContain(marker);
47|  }
48|
49|  const articles = JSON.parse(raw);
50|  expect(Array.isArray(articles)).toBe(true);
51|  for (const article of articles) {
52|    const keys = Object.keys(article);
53|    const nonPublic = keys.filter((key) => !ARTICLES_PUBLIC_FIELDS.has(key));
54|    expect(nonPublic, `field nội bộ trong /api/articles: ${nonPublic.join(', ')}`).toEqual([]);
55|  }
56|  return articles;
57|}
58|
59|// Mọi bài PUBLISHED thuộc nhóm đang hiển thị phải hiện thật trong DOM.
60|export async function expectFeedRenderedInDom(page, articles) {
61|  const visible = articles.filter((article) => article.category === DEFAULT_GROUP_ID);
62|  for (const article of visible) {
63|    await expect(
64|      page.locator('.article-card', { hasText: article.title }).first(),
65|      `bài "${article.title}" không hiển thị trong feed`
66|    ).toBeVisible();
67|  }
68|}
69|
70|export async function expectNoProvenanceInVisibleUi(page) {
71|  const bodyText = (await page.innerText('body')).toLowerCase();
72|  for (const marker of PROVENANCE_MARKERS) {
73|    expect(bodyText, `marker nội bộ "${marker}" lộ trong UI public`).not.toContain(marker);
74|  }
